const $ = id => document.getElementById(id);
let selected=null, installed=false, busy=false;
const candidates=window.marsAdapter.candidates;
$('markers').innerHTML=candidates.map(c=>`<circle cx="${c.x}" cy="${c.y}" r="18" fill="#342c27" stroke="#f4ac78"/><text x="${c.x}" y="${c.y+5}" text-anchor="middle" fill="#fff">${c.id}</text>`).join('');
for(const c of candidates){const b=document.createElement('button');b.className='candidate';b.textContent=`후보지 ${c.id}`;b.onclick=()=>{if(installed||busy)return;selected=c.id;document.querySelectorAll('.candidate').forEach(x=>x.setAttribute('aria-pressed',x===b));$('install').disabled=false;$('install').textContent=`${c.id}에 중계소 설치`;};b.setAttribute('aria-pressed','false');$('candidates').append(b);}
$('start').onclick=()=>{$('brief').hidden=true;$('game').hidden=false;};
$('install').onclick=async()=>{if(!selected||installed||busy)return;busy=true;$('install').disabled=true;$('install').textContent='분석 중…';try{const r=await window.marsAdapter.analyze(selected);if(typeof r.baseToRelay!=='boolean'||typeof r.relayToTarget!=='boolean')throw new Error('분석 결과 형식을 확인해 주세요.');installed=true;$('remaining').textContent='0';const success=r.baseToRelay&&r.relayToTarget;const c=candidates.find(c=>c.id===selected);$('paths').innerHTML=[[90,300,c.x,c.y,r.baseToRelay],[c.x,c.y,580,230,r.relayToTarget]].map(([x1,y1,x2,y2,ok])=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${ok?'#8cd7b0':'#ff876c'}" stroke-width="3" stroke-dasharray="${ok?'0':'7 7'}"/>`).join('');$('result').hidden=false;$('result').innerHTML=`<small>${r.mode==='mock'?'가상 분석 결과 · 연동 테스트':'분석 결과'}</small><h2>${success?'✓ LEVEL 1 COMPLETE':'가시선 경로가 차단되었습니다.'}</h2><p>기지 → 중계소: ${r.baseToRelay?'확보':'차단'} / 중계소 → 마지막 확인 위치: ${r.relayToTarget?'확보':'차단'}</p><p>${success?'마지막 확인 위치까지 가시선 경로를 확보했습니다. 우주비행사 발견 여부는 확인되지 않았습니다.':'다시 도전 버튼을 눌러 다른 후보지를 선택하세요.'}</p>`;$('install').textContent='중계소 배치 완료';}catch(e){$('result').hidden=false;$('result').textContent=`분석 실패: ${e.message}`;$('install').disabled=false;$('install').textContent='분석 다시 시도';}finally{busy=false;}};
$('reset').onclick=()=>{if(busy)return;selected=null;installed=false;$('remaining').textContent='1';$('result').hidden=true;$('paths').innerHTML='';$('install').disabled=true;$('install').textContent='후보지를 선택하세요';document.querySelectorAll('.candidate').forEach(b=>b.setAttribute('aria-pressed','false'));};
